 static void MakeWoodTexture(){int w=1024,h=1024;var t=new Texture2D(w,h,TextureFormat.RGB24,false);var colors=new Color[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){float warp=Mathf.PerlinNoise(x*.003f,y*.004f)*12,f=Mathf.PerlinNoise(x*.006f,(y+warp)*.20f),fine=Mathf.PerlinNoise(x*.025f,(y+warp)*.8f);float n=.83f+f*.13f+fine*.04f;colors[y*w+x]=new Color(n,n,n);}t.SetPixels(colors);t.Apply();File.WriteAllBytes(A+"Textures/OakGrain.png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(A+"Textures/OakGrain.png");var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(A+"Textures/OakGrain.png");wood.SetColor("_BaseColor",C("BAA17E"));wood.SetTexture("_BaseMap",texture);wood.SetTextureScale("_BaseMap",new Vector2(.14f,.65f));darkwood.SetTexture("_BaseMap",texture);darkwood.SetTextureScale("_BaseMap",new Vector2(.5f,2));EditorUtility.SetDirty(wood);EditorUtility.SetDirty(darkwood);}
 static void RestyleTrain(){var replacements=new Dictionary<string,Material>();foreach(var r in engine.locomotive.GetComponentsInChildren<Renderer>(true)){if(r is ParticleSystemRenderer)continue;var part=r.GetComponentInParent<LocomotivePart>();var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){var m=mats[i];if(!m)continue;string n=m.name;bool paint=n.Contains("Enamel")||n.Contains("Green")||n=="FireboxWrapperPBR",wheel=part&&part.partId=="P09";if(paint)mats[i]=n.Contains("Buffer")?red:wheel?red:navy;else if(n.Contains("Brass"))mats[i]=brass;else if(n=="MachinedSteel"||n=="MachinedNickel"||n=="SatinMachinedSteel"||n=="TurnedSteel")mats[i]=steel;else if(n=="GraphiteSteel"||n=="CastSteel")mats[i]=black;else if(n=="FireboxBackheadPBR"||n=="SmokeboxBlack"||n=="RolledRoofSteel"||n=="GraphiteCylinder"||n=="CylinderEnamel")mats[i]=black;else if(n.StartsWith("P11_")||n.StartsWith("P12_")||n.StartsWith("P14_")||n.StartsWith("P15")||n.StartsWith("P16_"))mats[i]=steel;}r.sharedMaterials=mats;}
  var thermal=engine.GetComponent<LocomotiveThermalEffects>();if(thermal.smoke){var main=thermal.smoke.main;main.startColor=new Color(.72f,.76f,.77f,.40f);main.startSize=new ParticleSystem.MinMaxCurve(.48f,.75f);main.startLifetime=4.5f;var col=thermal.smoke.colorOverLifetime;col.enabled=true;var g=new Gradient();g.SetKeys(new[]{new GradientColorKey(C("D1D1C9"),0),new GradientColorKey(C("ECECE4"),1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(.64f,.1f),new GradientAlphaKey(.35f,.65f),new GradientAlphaKey(0,1)});col.color=g;}
